import re


def parse_script(text: str) -> dict:
    """Parse a dialogue script into a structured graph with nodes and edges.

    Returns a dict with 'nodes' and 'edges' keys.
    """
    nodes = []
    edges = []
    node_map: dict[str, dict] = {}

    # Split into sections — each starts with [SectionName] at line beginning
    raw_sections = re.split(r'\n(?=\[)', text.strip())

    for section in raw_sections:
        section = section.strip()
        if not section:
            continue

        lines = section.split('\n')
        header_match = re.match(r'\[(.+?)\]', lines[0].strip())
        if not header_match:
            continue

        node_id = header_match.group(1)
        content = [l.strip() for l in lines[1:] if l.strip()]

        if not content:
            continue

        first_line = content[0]

        if re.match(r'^\d+\.', first_line):
            # ---- choice node ----
            for line in content:
                m = re.match(r'^\d+\.\s*(.+?)\s*->\s*(.+?)$', line)
                if m:
                    option_text = m.group(1).strip()
                    target = m.group(2).strip()
                    edges.append({
                        'from': node_id,
                        'to': target,
                        'text': option_text,
                    })

            readable = re.sub(r'([a-z])([A-Z])', r'\1 \2', node_id)
            node = {
                'id': node_id,
                'text': readable,
                'speaker': '',
                'type': 'choice',
            }
            nodes.append(node)
            node_map[node_id] = node
        else:
            # ---- line node ----
            m = re.match(r'^(.+?):\s*(.+?)\s*->\s*(.+?)$', first_line)
            if m:
                speaker = m.group(1).strip()
                dialogue = m.group(2).strip()
                target = m.group(3).strip()

                node = {
                    'id': node_id,
                    'text': dialogue,
                    'speaker': speaker,
                    'type': 'line',
                }
                nodes.append(node)
                node_map[node_id] = node

                edges.append({
                    'from': node_id,
                    'to': target,
                    'text': '',
                })

    # Add synthetic "End" terminal node when referenced but not defined
    if any(e['to'] == 'End' for e in edges) and 'End' not in node_map:
        end_node = {
            'id': 'End',
            'text': 'End',
            'speaker': '',
            'type': 'end',
        }
        nodes.append(end_node)
        node_map['End'] = end_node

    return {'nodes': nodes, 'edges': edges}


def validate_graph(graph: dict) -> list[str]:
    """Validate the parsed graph and return a list of issues (empty = valid)."""
    issues = []
    nodes = {n['id'] for n in graph['nodes']}
    node_list = [n['id'] for n in graph['nodes']]
    edges = graph['edges']

    if not node_list:
        issues.append('No nodes found')
        return issues

    start_id = node_list[0]

    # Constraint 1: all nodes reachable from the first node
    adj = {nid: [] for nid in nodes}
    for e in edges:
        adj[e['from']].append(e['to'])

    visited = set()
    stack = [start_id]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in visited:
                stack.append(nxt)

    unreachable = nodes - visited
    if unreachable:
        issues.append(
            f'Unreachable nodes from "{start_id}": {sorted(unreachable)}'
        )

    # Constraint 2: all edge targets must exist as nodes (End is allowed)
    for e in edges:
        if e['to'] not in nodes and e['to'] != 'End':
            issues.append(
                f'Edge target "{e["to"]}" (from "{e["from"]}") does not exist'
            )

    return issues


def generate_dot(graph: dict) -> str:
    """Generate a Graphviz DOT representation of the dialogue graph."""
    lines = ['digraph Dialogue {']
    lines.append('  rankdir=TB;')
    lines.append('  node [fontname="Helvetica"];')
    lines.append('  edge [fontname="Helvetica", fontsize=10];')
    lines.append('')

    for node in graph['nodes']:
        nid = node['id']
        label = node['text'].replace('"', '\\"')
        if node['type'] == 'line':
            speaker = node['speaker'].replace('"', '\\"')
            full_label = f'{speaker}: {label}'
            lines.append(
                f'  "{nid}" [label="{full_label}", shape=box, '
                f'style=filled, fillcolor=lightblue];'
            )
        elif node['type'] == 'choice':
            lines.append(
                f'  "{nid}" [label="{label}", shape=diamond, '
                f'style=filled, fillcolor=lightyellow];'
            )
        elif node['type'] == 'end':
            lines.append(
                f'  "{nid}" [label="{label}", shape=doublecircle, '
                f'style=filled, fillcolor=lightgreen];'
            )

    lines.append('')
    for edge in graph['edges']:
        src = edge['from']
        dst = edge['to']
        label = edge['text'].replace('"', '\\"')
        if label:
            lines.append(f'  "{src}" -> "{dst}" [label="{label}"];')
        else:
            lines.append(f'  "{src}" -> "{dst}";')

    lines.append('}')
    return '\n'.join(lines)


if __name__ == '__main__':
    with open('/app/script.txt', 'r') as f:
        script_text = f.read()

    graph = parse_script(script_text)

    issues = validate_graph(graph)
    if issues:
        print('Validation issues:')
        for issue in issues:
            print(f'  - {issue}')
        raise SystemExit(1)

    print(f'Parsed {len(graph["nodes"])} nodes and {len(graph["edges"])} edges')

    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)

    dot = generate_dot(graph)
    with open('/app/dialogue.dot', 'w') as f:
        f.write(dot)

    print('Wrote /app/dialogue.json and /app/dialogue.dot')", "path": "/app/solution.py"}: Editing /app/solution.py

